  1	#!/usr/bin/env node
  2	// The provenance log's one tool (the provenance design, #2136): every flow that
  3	// creates or changes an element appends through it, the marking pass runs through it,
  4	// and a maintainer checks a pack with it. Two roots - a canon's `packs/<id>` and a
  5	// member's `.claudinite/local/packs/<id>` - resolved from the id, or `--all` for every
  6	// pack under both. The grammar and the codemods are the engine helper's
  7	// (engine/checks/helpers/provenance.mjs); this is the command line over them, and
  8	// the parts that need git or a scrub.
  9	//
 10	//   node <path-to-this-file> mark <pack>|--all [--dry-run]
 11	//   node <path-to-this-file> check <pack>|--all
 12	//   node <path-to-this-file> convert-references <pack>|--all
 13	//   node <path-to-this-file> append <pack> <element> [--kind <kind>] [--date <YYYY-MM-DD>] [--changed] < entry.md
 14	//   node <path-to-this-file> reduce <file> [--public]
 15	//   node <path-to-this-file> history <pack> <element>
 16	//   node <path-to-this-file> brief <pack> [<element>…]
 17	//   node <path-to-this-file> apply <pack> <brief.md>
 18	//
 19	// In a member the path is .claudinite/shared/packs/claudinite-growth/provenance.mjs; in
 20	// the canon, packs/claudinite-growth/provenance.mjs. The append reads one entry in the
 21	// file grammar from stdin - `## <date> · <kind> · <title>` and its `- **Field:** …`
 22	// lines - and refuses one that carries a secret, since a decision log is prose an
 23	// agent writes and the one place nothing else scans.
 24	import { execFileSync } from 'node:child_process';
 25	import { readFileSync } from 'node:fs';
 26	import { join } from 'node:path';
 27	import { pathToFileURL } from 'node:url';
 28	// A namespace import, guarded in `main`: the pack and engine lanes deliver on separate
 29	// cadences, and a mount whose engine predates the helper must say so rather than fault
 30	// on a missing named export.
 31	import * as provenance from '../../engine/checks/helpers/provenance.mjs';
 32	import * as conventions from '../../engine/pack_loader/pack-conventions.mjs';
 33	import { scrub } from './capture-log.mjs';
 34	
 35	// The version log's name, with the same lane-skew fallback as the helper import above.
 36	const VERSIONS_FILE = conventions.VERSIONS_FILE ?? 'VERSIONS.md';
 37	
 38	const {
 39	  checkoutIo, auditPack, markPack, convertReferences, appendedText, parseEntryText, packCarriers,
 40	  provenanceFiles, reduceFile, fileOfId, elementIdOf, ruleBlocks, skillShape, parseEntries, renderEntry,
 41	  PACK_ROOTS, PROVENANCE_DIR, DECLINED_FILE, DECLINED_KIND, PACK_ELEMENT,
 42	} = provenance;
 43	
 44	const USAGE = `usage: provenance.mjs <command> …
 45	  mark <pack>|--all [--dry-run]          markers, bodies and empty files for every carrier
 46	  check <pack>|--all                     what each file is named by, and every fault
 47	  convert-references <pack>|--all        the references.md of a pack into its elements' files
 48	  append <pack> <element> [--kind K] [--date D] [--changed] < entry.md
 49	  reduce <file> [--public]               the promotion reduction, to stdout
 50	  history <pack> <element>               one element's raw evidence from git, VERSIONS.md and the README
 51	  brief <pack> [<element>…]              the backfill brief: every pull request once, a draft entry per event
 52	  apply <pack> <brief.md>                append every drafted entry of an edited brief, each once`;
 53	
 54	// --- packs and roots ---------------------------------------------------------------
 55	
 56	export function resolvePack(root, id, io = checkoutIo(root)) {
 57	  if (id.includes('/')) return io.exists(`${id}/pack.mjs`) ? id.replace(/\/+$/, '') : null;
 58	  for (const r of PACK_ROOTS) if (io.exists(`${r}/${id}/pack.mjs`)) return `${r}/${id}`;
 59	  return null;
 60	}
 61	
 62	export function allPacks(io) {
 63	  const out = [];
 64	  for (const r of PACK_ROOTS) for (const name of (io.listDir(r) ?? []).sort()) if (io.exists(`${r}/${name}/pack.mjs`)) out.push(`${r}/${name}`);
 65	  return out;
 66	}
 67	
 68	// A copy-on-write io over another: what `--dry-run` runs the codemods against, so the
 69	// report is the real one and the tree is untouched.
 70	export function overlayIo(base) {
 71	  const written = new Map();
 72	  const removed = new Set();
 73	  const listDir = (p) => {
 74	    if (written.has(p)) return null;
 75	    const names = new Set((removed.has(p) ? null : base.listDir(p)) ?? []);
 76	    let any = names.size > 0 || base.listDir(p) !== null;
 77	    for (const w of written.keys()) {
 78	      if (w.startsWith(`${p}/`)) { names.add(w.slice(p.length + 1).split('/')[0]); any = true; }
 79	    }
 80	    for (const r of removed) names.delete(r.slice(p.length + 1));
 81	    return any ? [...names] : null;
 82	  };
 83	  return {
 84	    exists: (p) => (removed.has(p) ? false : written.has(p) || base.exists(p)),
 85	    read: (p) => (removed.has(p) ? null : written.has(p) ? written.get(p) : base.read(p)),
 86	    write: (p, t) => { written.set(p, t); removed.delete(p); },
 87	    remove: (p) => { removed.add(p); written.delete(p); },
 88	    listDir,
 89	  };
 90	}
 91	
 92	const git = (root, ...args) => { try { return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { return ''; } };
 93	
 94	// --- the commands ------------------------------------------------------------------
 95	
 96	export function mark(root, packs, { dryRun = false } = {}) {
 97	  const real = checkoutIo(root);
 98	  const io = dryRun ? overlayIo(real) : real;
 99	  const lines = [];
100	  let empty = 0;
101	  for (const pack of packs) {
102	    lines.push(...markPack(pack, io));
103	    empty += auditPack(pack, io).empty.length;
104	  }
105	  lines.push(`${empty} empty provenance file${empty === 1 ? '' : 's'} under ${packs.length === 1 ? packs[0] : `${packs.length} packs`}${dryRun ? ' (dry run: nothing written)' : ''}`);
106	  return { lines, empty };
107	}
108	
109	// The audit as text: what each file is named by, then every fault. Exit status is the
110	// caller's: faults are anything but pending history.
111	export function check(root, packs) {
112	  const io = checkoutIo(root);
113	  const lines = [];
114	  let faults = 0;
115	  for (const pack of packs) {
116	    const a = auditPack(pack, io);
117	    const namedBy = new Map();
118	    const name = (id, by) => { if (!namedBy.has(id)) namedBy.set(id, []); namedBy.get(id).push(by); };
119	    for (const r of a.carriers.rules) if (r.slug) name(r.slug, `rule "${r.trigger}"`);
120	    for (const g of a.carriers.guidelines) if (g.slug) name(g.slug, `guideline "${g.trigger}" (${g.skill})`);
121	    for (const s of a.carriers.skills) if (s.present) name(s.name, `skill ${s.name} (${s.body ?? 'no body'})`);
122	    for (const c of a.carriers.checks) name(elementIdOf(c.id), `check ${c.id}`);
123	    for (const t of a.carriers.tasks) name(t.id, `task ${t.id}`);
124	    if (a.carriers.manifest) name(PACK_ELEMENT, 'the manifest');
125	    lines.push(`${pack}/${PROVENANCE_DIR}/`);
126	    for (const [id, f] of [...a.files].sort()) lines.push(`  ${fileOfId(id)} ← ${(namedBy.get(id) ?? ['nothing']).join(', ')}${f.status === 'retired' ? ' (retired)' : f.empty ? ' (empty)' : ''}`);
127	    const fault = (file, line, what) => { faults++; lines.push(`  ${file}${line ? `:${line}` : ''}: ${what}`); };
128	    for (const u of a.unmarked) fault(u.file, u.line, `"${u.trigger}" ends with no marker`);
129	    for (const d of a.dangling) fault(d.file, d.line, `${d.carrier} names ${fileOfId(d.id)}, which is ${d.retired ? 'retired' : 'no file'}`);
130	    for (const u of a.unnamed) fault(u.file, null, 'live, and named by no carrier');
131	    for (const n of a.noBody) fault(n.file, null, `skill ${n.skill} declares no body`);
132	    for (const m of a.markerInWorkflow) fault(m.file, m.line, `"${m.trigger}" carries a marker inside a workflow skill`);
133	    for (const e of a.parseErrors) fault(e.file, e.line, e.what);
134	    for (const e of a.entryFaults) fault(e.file, e.line, e.what);
135	    if (a.referencesDoc) fault(a.referencesDoc, null, 'a references.md still exists - convert-references retires it');
136	  }
137	  return { lines, faults };
138	}
139	
140	// The earliest commit that added a references key, as a YYYY-MM-DD date - what dates
141	// a converted entry where git is there to read.
142	export function referenceDateOf(root, doc) {
143	  return (key) => {
144	    const out = git(root, 'log', '--reverse', '--format=%as', `-S**(${key})**`, '--', doc).trim().split('\n')[0];
145	    return /^\d{4}-\d{2}-\d{2}$/.test(out ?? '') ? out : null;
146	  };
147	}
148	
149	export function convert(root, packs) {
150	  const io = checkoutIo(root);
151	  const lines = [];
152	  for (const pack of packs) lines.push(...convertReferences(pack, io, { dateOf: referenceDateOf(root, `${pack}/references.md`) }));
153	  return lines;
154	}
155	
156	// The elements the working tree's change touched, for `append --changed`: a rule whose
157	// normalized text differs from HEAD's, a check module, a task or the manifest that
158	// changed, a skill whose file changed (its guidelines by text).
159	export function changedElements(root, pack) {
160	  const io = checkoutIo(root);
161	  const changed = new Set([...git(root, 'diff', '--name-only', 'HEAD', '--', pack).split('\n'), ...git(root, 'ls-files', '--others', '--exclude-standard', '--', pack).split('\n')].filter(Boolean));
162	  const head = { ...io, read: (p) => { const t = git(root, 'show', `HEAD:${p}`); return t === '' && !git(root, 'cat-file', '-e', `HEAD:${p}`) ? null : t; } };
163	  const out = new Set();
164	  const now = packCarriers(pack, io);
165	  const before = packCarriers(pack, head);
166	  const byTrigger = (list) => new Map(list.map((r) => [r.trigger, r]));
167	  const prose = (nowList, thenList) => {
168	    const then = byTrigger(thenList);
169	    for (const r of nowList) {
170	      if (!r.slug || !changed.has(r.file)) continue;
171	      const was = then.get(r.trigger);
172	      if (!was || was.text !== r.text) out.add(r.slug);
173	    }
174	  };
175	  prose(now.rules, before.rules);
176	  prose(now.guidelines, before.guidelines);
177	  for (const s of now.skills) if (s.present && changed.has(s.file)) out.add(s.name);
178	  for (const c of now.checks) if (changed.has(c.file)) out.add(elementIdOf(c.id));
179	  for (const t of now.tasks) if ([...changed].some((f) => f.startsWith(`${t.dir}/`))) out.add(t.id);
180	  if (now.manifest && changed.has(`${pack}/pack.mjs`)) out.add(PACK_ELEMENT);
181	  return [...out].sort();
182	}
183	
184	export function append(root, pack, elements, entryText, { kind = null, date = null } = {}) {
185	  const io = checkoutIo(root);
186	  const scrubbed = scrub(entryText);
187	  if (scrubbed !== entryText) return { problems: ['the entry carries what reads as a secret; a decision log is the one place nothing else scans, so it is refused whole'] };
188	  const parsed = parseEntryText(entryText);
189	  if (parsed.problems.length) return { problems: parsed.problems };
190	  const entry = { ...parsed.entry, ...(kind ? { kind } : {}), ...(date ? { date } : {}) };
191	  const written = [];
192	  for (const element of elements) {
193	    const declined = element === DECLINED_KIND || element === '_declined';
194	    const file = `${pack}/${PROVENANCE_DIR}/${declined ? DECLINED_FILE : fileOfId(element)}`;
195	    if (!declined && !io.exists(file)) return { problems: [`${file} does not exist - no carrier of ${pack} names an element "${element}" (run mark, or check the id)`] };
196	    const result = appendedText(io.read(file) ?? '', entry, declined ? { kinds: [DECLINED_KIND], firstKind: null } : {});
197	    if (result.problems.length) return { problems: result.problems.map((p) => `${file}: ${p}`) };
198	    io.write(file, result.text);
199	    written.push(file);
200	  }
201	  return { problems: [], written };
202	}
203	
204	// The backfill brief: the carrier's commits through every rename, a pickaxe on the
205	// rule's lead-in, the pull requests those commits name, the VERSIONS.md rows naming
206	// them, and the README's history sentences. Tracker comments live on GitHub and are
207	// the session's to read.
208	export function history(root, pack, element) {
209	  const io = checkoutIo(root);
210	  const c = packCarriers(pack, io);
211	  const files = new Set();
212	  const triggers = [];
213	  for (const r of [...c.rules, ...c.guidelines]) if (r.slug === element) { files.add(r.file); triggers.push(r.trigger); }
214	  for (const s of c.skills) if (s.name === element) files.add(s.file);
215	  for (const x of c.checks) if (elementIdOf(x.id) === element) files.add(x.file);
216	  for (const t of c.tasks) if (t.id === element) files.add(t.dir);
217	  if (element === PACK_ELEMENT) files.add(`${pack}/pack.mjs`);
218	  const lines = [`# ${pack} · ${element}`];
219	  if (!files.size) { lines.push('named by no carrier of this pack'); return lines; }
220	  const prs = new Set();
221	  const note = (commits) => { for (const m of commits.matchAll(/\(#(\d+)\)/g)) prs.add(m[1]); };
222	  for (const f of files) {
223	    lines.push(`\n## commits touching ${f}`);
224	    const log = git(root, 'log', '--follow', '--format=%h %as %s', '--', f);
225	    lines.push(log.trim() || '(none - is the clone shallow?)');
226	    note(log);
227	  }
228	  for (const t of triggers) {
229	    lines.push(`\n## commits adding or removing "${t}"`);
230	    const log = git(root, 'log', '--format=%h %as %s', `-S${t}`, '--', pack);
231	    lines.push(log.trim() || '(none)');
232	    note(log);
233	  }
234	  lines.push('\n## pull requests those commits name');
235	  lines.push(prs.size ? [...prs].sort((a, b) => a - b).map((n) => `#${n}`).join(' ') : '(none)');
236	  const versions = io.read(`${pack}/${PROVENANCE_DIR}/${VERSIONS_FILE}`);
237	  if (versions) {
238	    lines.push('\n## VERSIONS.md rows naming them');
239	    const rows = versions.split('\n').filter((l) => l.startsWith('|') && [...prs].some((n) => l.includes(`#${n}`)));
240	    lines.push(rows.join('\n') || '(none)');
241	  }
242	  const readme = io.read(`${pack}/README.md`);
243	  if (readme) {
244	    lines.push('\n## README sentences that read as history');
245	    const tells = readme.split(/(?<=[.!?])\s+/).filter((s) => /#\d+|\buntil\b|\bdistilled from\b|\bkept as\b|\breplaced\b|\babsorbed\b|\b20\d\d-\d\d-\d\d\b/.test(s) || triggers.some((t) => s.includes(t)));
246	    lines.push(tells.map((s) => `- ${s.replace(/\s+/g, ' ').trim()}`).join('\n') || '(none)');
247	  }
248	  lines.push('\n## tracker comments');
249	  lines.push('read the promote tracker and the extract issues on GitHub; git does not hold them');
250	  return lines;
251	}
252	
253	// --- the backfill brief and its apply -----------------------------------------------
254	//
255	// A pack's history is a sequence of pull requests, each bearing or changing several
256	// elements, so the brief is written pull request first: the squash commit's body once
257	// (a merge here carries the whole review conversation's conclusion in it), then one
258	// draft entry per element and event with every field git can vouch for - the date, the
259	// kind, the actor by handle, the model from the trailer, the carrier as Mechanism, and
260	// Landed with the version VERSIONS.md cut for it. What git cannot vouch for - Source,
261	// Reason, Rejected, Retire when - is left out, never filled: the draft is a fact the
262	// session extends with the decision, or deletes where the commit was not one.
263	//
264	// An element's events are read from the carrier's own history rather than a pickaxe: a
265	// rule is walked back through every commit of its file - by slug, then by trigger, then
266	// by text - and is born where it first appears and reworded where its normalized text
267	// changed; a skill, a check, a task and the manifest are born at the oldest commit of
268	// their file and every later commit is a candidate the session judges. A commit that
269	// touched many packs is a sweep - a re-wrap, a rename, a marking pass - and is listed
270	// once, never drafted onto an element: the precedent records a sweep on `_pack.md`, and
271	// only where it changed the pack's shape.
272	
273	const SWEEP_PACKS = 5;
274	const TRAILER = /^(?:co-authored-by|claude-session|signed-off-by|reviewed-by|refs|fixes|closes|resolves):?\s/i;
275	const MODEL_TRAILER = /^co-authored-by:\s*(Claude\b[^<]*?)\s*</i;
276	const REFERENCED = /\b(?:Refs|Fixes|Closes|Resolves)\s*:?\s*#(\d+)/gi;
277	const PR_AT_END = /\s*\(#(\d+)\)\s*$/;
278	const ENTRY_FENCE = /^```entry (\S+)\s*$/;
279	const BODY_LINES = 60;
280	
281	// One commit, read once: what the squash merge carried, and how many packs it touched.
282	function commitInfo(root, sha, cache) {
283	  if (cache.has(sha)) return cache.get(sha);
284	  const [full, short, date, email, subject, body = ''] = git(root, 'show', '-s', '--format=%H%x00%h%x00%as%x00%ae%x00%s%x00%b', sha).split('\0');
285	  const models = new Set();
286	  const lines = [];
287	  for (const l of (body ?? '').split('\n')) {
288	    const m = MODEL_TRAILER.exec(l.trim());
289	    if (m) { models.add(m[1].trim()); continue; }
290	    if (TRAILER.test(l.trim())) continue;
291	    lines.push(l.trimEnd());
292	  }
293	  const pr = PR_AT_END.exec(subject ?? '')?.[1] ?? null;
294	  const refs = [...new Set([...(body ?? '').matchAll(REFERENCED)].map((m) => m[1]).filter((n) => n !== pr))];
295	  const packs = new Set();
296	  const files = [];
297	  for (const f of git(root, 'diff-tree', '--root', '-r', '-m', '--first-parent', '--no-commit-id', '--name-only', sha).split('\n')) {
298	    if (f) files.push(f);
299	    const m = /^(?:\.claudinite\/local\/)?packs\/([^/]+)\//.exec(f);
300	    if (m) packs.add(m[1]);
301	  }
302	  // GitHub's own squash line names a bare "Claude" beside the session's trailer.
303	  if (models.size > 1) models.delete('Claude');
304	  const info = {
305	    sha: full, short, date, subject, pr, refs, models: [...models], files,
306	    title: (subject ?? '').replace(PR_AT_END, '').trim(),
307	    handle: /^\d+\+([^@]+)@users\.noreply\.github\.com$/.exec(email ?? '')?.[1] ?? null,
308	    body: lines.join('\n').replace(/\n{3,}/g, '\n\n').trim(),
309	    sweep: packs.size >= SWEEP_PACKS,
310	  };
311	  cache.set(sha, info);
312	  return info;
313	}
314	
315	const repoOwner = (root) => /github\.com[:/]([^/]+)\//.exec(git(root, 'remote', 'get-url', 'origin'))?.[1] ?? null;
316	
317	// The commits touching a path, newest first, each with the path it had then.
318	function commitsOf(root, path, { follow = true } = {}) {
319	  const out = [];
320	  let sha = null;
321	  for (const line of git(root, 'log', ...(follow ? ['--follow'] : []), '--format=%x01%H', '--name-only', '--', path).split('\n')) {
322	    if (line.startsWith('\x01')) { sha = line.slice(1); out.push({ sha, path }); continue; }
323	    if (line.trim() && sha) out[out.length - 1].path = line.trim();
324	  }
325	  return out;
326	}
327	
328	// A rule's events, walked back through its file: born where it is first found,
329	// reworded at each commit after which its text differs.
330	function ruleEvents(root, file, rule, blocksOf) {
331	  let state = rule;
332	  let newer = null;
333	  const events = [];
334	  for (const { sha, path } of commitsOf(root, file)) {
335	    const text = git(root, 'show', `${sha}:${path}`);
336	    const blocks = text ? blocksOf(text) : [];
337	    const found = (state.slug && blocks.find((b) => b.slug === state.slug))
338	      || blocks.find((b) => b.trigger === state.trigger)
339	      || blocks.find((b) => b.text === state.text);
340	    if (!found) break;
341	    if (newer && found.text !== state.text) events.push({ kind: 'reworded', sha: newer });
342	    state = found;
343	    newer = sha;
344	  }
345	  if (newer) events.push({ kind: 'born', sha: newer });
346	  return events;
347	}
348	
349	// A file-borne element's events: born at the oldest commit of its path, every later
350	// commit a reworded candidate - except one that changed nothing but a version line,
351	// which is the bump no entry is owed for.
352	function fileEvents(root, path, { follow = true } = {}) {
353	  const commits = commitsOf(root, path, { follow });
354	  if (!commits.length) return [];
355	  const bump = (c) => {
356	    const changed = git(root, 'show', '--format=', c.sha, '--', c.path).split('\n').filter((l) => /^[-+](?![-+])/.test(l));
357	    return changed.length > 0 && changed.every((l) => /^[-+]\s*version:\s*['"]?[\d.]+['"]?,?\s*$/.test(l));
358	  };
359	  return [...commits.slice(0, -1).filter((c) => !bump(c)).map((c) => ({ kind: 'reworded', sha: c.sha })), { kind: 'born', sha: commits[commits.length - 1].sha }];
360	}
361	
362	// The version a commit landed in: the VERSIONS.md row naming its pull request, else
363	// the manifest's own history - the version the commit itself set, or the first cut
364	// after it - since the weekly history task writes the rows late.
365	function versionRows(io, pack) {
366	  return (io.read(`${pack}/${PROVENANCE_DIR}/${VERSIONS_FILE}`) ?? '').split('\n')
367	    .map((l) => /^\|\s*([^|]+?)\s*\|\s*(\d{4}-\d{2}-\d{2})\s*\|\s*(.*?)\s*\|\s*$/.exec(l))
368	    .filter(Boolean)
369	    .map(([, version, date, what]) => ({ version, date, what }));
370	}
371	function versionReader(root, pack) {
372	  const at = new Map();
373	  const versionAt = (sha) => {
374	    if (!at.has(sha)) at.set(sha, /\bversion:\s*['"]?([\d.]+)/.exec(git(root, 'show', `${sha}:${pack}/pack.mjs`))?.[1] ?? null);
375	    return at.get(sha);
376	  };
377	  return (info) => {
378	    const own = versionAt(info.sha);
379	    if (own && own !== versionAt(`${info.sha}^`)) return own;
380	    for (const sha of git(root, 'log', '--reverse', '--format=%H', `${info.sha}..HEAD`, '--', `${pack}/pack.mjs`).split('\n').filter(Boolean)) {
381	      const v = versionAt(sha);
382	      if (v && v !== own) return v;
383	    }
384	    return null;
