  for (const line of git(root, 'log', ...(follow ? ['--follow'] : []), '--format=%x01%H', '--name-only', '--', path).split('\n')) {
    if (line.startsWith('\x01')) { sha = line.slice(1); out.push({ sha, path }); continue; }
